INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (108,3,'Al-Kawthar','إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ','کچھ شک نہیں کہ تمہارا دشمن ہی بےاولاد رہے گا','Only the one who hates you is truly cut off ˹from any goodness˺','और क़ुर्बानी दिया करो बेशक तुम्हारा दुश्मन बे औलाद रहेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (109,1,'Al-Kaafiroon','قُلۡ يَٰٓأَيُّهَا ٱلۡكَٰفِرُونَ','(اے پیغمبر ان منکران اسلام سے) کہہ دو کہ اے کافرو','Say, ˹O Prophet,˺ “O you disbelievers','(ऐ रसूल) तुम कह दो कि ऐ काफिरों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (109,2,'Al-Kaafiroon','لَآ أَعۡبُدُ مَا تَعۡبُدُونَ','جن (بتوں) کو تم پوچتے ہو ان کو میں نہیں پوجتا','I do not worship what you worship','तुम जिन चीज़ों को पूजते हो, मैं उनको नहीं पूजता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (109,3,'Al-Kaafiroon','وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ','اور جس (خدا) کی میں عبادت کرتا ہوں اس کی تم عبادت نہیں کرتے','nor do you worship what I worship','और जिस (ख़ुदा) की मैं इबादत करता हूँ उसकी तुम इबादत नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (109,4,'Al-Kaafiroon','وَلَآ أَنَا۠ عَابِدࣱ مَّا عَبَدتُّمۡ','اور (میں پھر کہتا ہوں کہ) جن کی تم پرستش کرتے ہوں ان کی میں پرستش کرنے والا نہیں ہوں','I will never worship what you worship','और जिन्हें तुम पूजते हो मैं उनका पूजने वाला नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (109,5,'Al-Kaafiroon','وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ','اور نہ تم اس کی بندگی کرنے والے (معلوم ہوتے) ہو جس کی میں بندگی کرتا ہوں','nor will you ever worship what I worship','और जिसकी मैं इबादत करता हूँ उसकी तुम इबादत करने वाले नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (109,6,'Al-Kaafiroon','لَكُمۡ دِينُكُمۡ وَلِيَ دِينِ','تم اپنے دین پر میں اپنے دین پر','You have your way, and I have my Way.”','तुम्हारे लिए तुम्हारा दीन मेरे लिए मेरा दीन');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (110,1,'An-Nasr','إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ','جب خدا کی مدد آ پہنچی اور فتح (حاصل ہو گئی)','When Allah’s ˹ultimate˺ help comes and the victory ˹over Mecca is achieved˺','ऐ रसूल जब ख़ुदा की मदद आ पहँचेगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (110,2,'An-Nasr','وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجࣰ ا','اور تم نے دیکھ لیا کہ لوگ غول کے غول خدا کے دین میں داخل ہو رہے ہیں','and you ˹O Prophet˺ see the people embracing Allah’s Way in crowds','और फतेह (मक्का) हो जाएगी और तुम लोगों को देखोगे कि गोल के गोल ख़ुदा के दीन में दाख़िल हो रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (110,3,'An-Nasr','فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا','تو اپنے پروردگار کی تعریف کے ساتھ تسبیح کرو اور اس سے مغفرت مانگو، بے شک وہ معاف کرنے والا ہے','then glorify the praises of your Lord and seek His forgiveness, for certainly He is ever Accepting of Repentance','तो तुम अपने परवरदिगार की तारीफ़ के साथ तसबीह करना और उसी से मग़फेरत की दुआ माँगना वह बेशक बड़ा माफ़ करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (111,1,'Al-Masad','تَبَّتۡ يَدَآ أَبِي لَهَبࣲ وَتَبَّ','ابولہب کے ہاتھ ٹوٹیں اور وہ ہلاک ہو','May the hands of Abu Lahab perish, and he ˹himself˺ perish','अबु लहब के हाथ टूट जाएँ और वह ख़ुद सत्यानास हो जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (111,2,'Al-Masad','مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ','نہ تو اس کا مال ہی اس کے کچھ کام آیا اور نہ وہ جو اس نے کمایا','Neither his wealth nor ˹worldly˺ gains will benefit him','(आख़िर) न उसका माल ही उसके हाथ आया और (न) उसने कमाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (111,3,'Al-Masad','سَيَصۡلَىٰ نَارࣰ ا ذَاتَ لَهَبࣲ‏','وہ جلد بھڑکتی ہوئی آگ میں داخل ہو گا','He will burn in a flaming Fire','वह बहुत भड़कती हुई आग में दाख़िल होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (111,4,'Al-Masad','وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ','اور اس کی جورو بھی جو ایندھن سر پر اٹھائے پھرتی ہے','and ˹so will˺ his wife, the carrier of ˹thorny˺ kindling','और उसकी जोरू भी जो सर पर ईंधन उठाए फिरती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (111,5,'Al-Masad','فِي جِيدِهَا حَبۡلࣱ مِّن مَّسَدِۭ','اس کے گلے میں مونج کی رسّی ہو گی','around her neck will be a rope of palm-fibre','और उसके गले में बटी हुई रस्सी बँधी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (112,1,'Al-Ikhlaas','قُلۡ هُوَ ٱللَّهُ أَحَدٌ','کہو کہ وہ (ذات پاک جس کا نام) الله (ہے) ایک ہے','Say, ˹O Prophet,˺ “He is Allah—One ˹and Indivisible˺','(ऐ रसूल) तुम कह दो कि ख़ुदा एक है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (112,2,'Al-Ikhlaas','ٱللَّهُ ٱلصَّمَدُ','معبود برحق جو بےنیاز ہے','Allah—the Sustainer ˹needed by all˺','ख़ुदा बरहक़ बेनियाज़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (112,3,'Al-Ikhlaas','لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ','نہ کسی کا باپ ہے اور نہ کسی کا بیٹا','He has never had offspring, nor was He born','न उसने किसी को जना न उसको किसी ने जना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (112,4,'Al-Ikhlaas','وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ','اور کوئی اس کا ہمسر نہیں','And there is none comparable to Him.”','और उसका कोई हमसर नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (113,1,'Al-Falaq','قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ','کہو کہ میں صبح کے پروردگار کی پناہ مانگتا ہوں','Say, ˹O Prophet,˺ “I seek refuge in the Lord of the daybreak','(ऐ रसूल) तुम कह दो कि मैं सुबह के मालिक की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (113,2,'Al-Falaq','مِن شَرِّ مَا خَلَقَ','ہر چیز کی بدی سے جو اس نے پیدا کی','from the evil of whatever He has created','हर चीज़ की बुराई से जो उसने पैदा की पनाह माँगता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (113,3,'Al-Falaq','وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ','اور شب تاریکی کی برائی سے جب اس کااندھیرا چھا جائے','and from the evil of the night when it grows dark','और अंधेरीरात की बुराई से जब उसका अंधेरा छा जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (113,4,'Al-Falaq','وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِي ٱلۡعُقَدِ','اور گنڈوں پر (پڑھ پڑھ کر) پھونکنے والیوں کی برائی سے','and from the evil of those ˹witches casting spells by˺ blowing onto knots','और गन्डों पर फूँकने वालियों की बुराई से');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (113,5,'Al-Falaq','وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ','اور حسد کرنے والے کی برائی سے جب حسد کرنے لگے','and from the evil of an envier when they envy.”','(जब फूँके) और हसद करने वाले की बुराई से');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (114,1,'An-Naas','قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ','کہو کہ میں لوگوں کے پروردگار کی پناہ مانگتا ہوں','Say, ˹O Prophet,˺ “I seek refuge in the Lord of humankind','(ऐ रसूल) तुम कह दो मैं लोगों के परवरदिगार');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (114,2,'An-Naas','مَلِكِ ٱلنَّاسِ','(یعنی) لوگوں کے حقیقی بادشاہ کی','the Master of humankind','लोगों के बादशाह');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (114,3,'An-Naas','إِلَٰهِ ٱلنَّاسِ','لوگوں کے معبود برحق کی','the God of humankind','लोगों के माबूद की (शैतानी)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (114,4,'An-Naas','مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ','(شیطان) وسوسہ انداز کی برائی سے جو (خدا کا نام سن کر) پیچھے ہٹ جاتا ہے','from the evil of the lurking whisperer—','वसवसे की बुराई से पनाह माँगता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (114,5,'An-Naas','ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ','جو لوگوں کے دلوں میں وسوسے ڈالتا ہے','who whispers into the hearts of humankind—','जो (ख़ुदा के नाम से) पीछे हट जाता है जो लोगों के दिलों में वसवसे डाला करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (114,6,'An-Naas','مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ','وہ جنّات میں سے (ہو) یا انسانوں میں سے','from among jinn and humankind.”','जिन्नात में से ख्वाह आदमियों में से');
